      <?php if (! empty($posts)): ?>
        <?php foreach ($posts as $post): ?>
          <?php
            $category = strtolower(trim((string) ($post['category'] ?? 'berita')));
            $categoryClass = preg_replace('/[^a-z0-9_-]/', '', $category);
            $dateValue = $post['published_at'] ?: ($post['created_at'] ?? '');
            $dateLabel = $dateValue ? date('d F Y', strtotime($dateValue)) : '';
            $excerpt = trim((string) ($post['excerpt'] ?? ''));
            if ($excerpt === '') {
                $excerpt = mb_substr(trim(strip_tags((string) ($post['content'] ?? ''))), 0, 145) . '…';
            }
            $title = (string) ($post['title'] ?? '');
          ?>
          <article class="news-card" data-category="<?= esc($category) ?>" data-search="<?= esc(mb_strtolower($title . ' ' . $excerpt . ' ' . $category)) ?>">
            <div class="cover-wrap">
              <?php if (! empty($post['image'])): ?>
                <img class="cover" src="<?= base_url('assets/images/posts/' . rawurlencode($post['image'])) ?>" alt="<?= esc($title) ?>" loading="lazy">
              <?php else: ?>
                <div class="cover-placeholder" aria-hidden="true">✦</div>
              <?php endif; ?>
              <span class="category-pill <?= esc($categoryClass) ?>"><?= esc($category) ?></span>
            </div>
            <div class="news-body">
              <div class="meta"><span>▦ &nbsp; <?= esc($dateLabel) ?></span><span>♟ &nbsp; <?= esc($post['author'] ?: 'Admin Website') ?></span></div>
              <h2><?= esc($title) ?></h2>
              <p><?= esc($excerpt) ?></p>
              <a class="read" href="<?= site_url('berita/' . rawurlencode($post['slug'])) ?>"><span>Baca selengkapnya →</span><span class="arrow" aria-hidden="true">→</span></a>
            </div>
          </article>
        <?php endforeach; ?>
      <?php else: ?>
        <div class="empty">Belum ada berita yang dipublikasikan. Silakan kunjungi kembali nanti.</div>
      <?php endif; ?>
      <div class="empty hidden" id="no-results">Berita tidak ditemukan. Coba kata kunci atau kategori lain.</div>
    </section>

