<script>
(function () {
  const cards = Array.from(document.querySelectorAll('.news-card'));
  const filters = Array.from(document.querySelectorAll('.filter'));
  const input = document.getElementById('search-input');
  const noResults = document.getElementById('no-results');
  let activeCategory = 'all';

  document.querySelectorAll('[data-count]').forEach(function (badge) {
    const category = badge.dataset.count;
    const count = category === 'all'
      ? cards.length
      : cards.filter(card => card.dataset.category === category).length;
    badge.textContent = count;
  });

  function applyFilters() {
    const query = (input.value || '').trim().toLocaleLowerCase('id');
    let visible = 0;
    cards.forEach(function (card) {
      const categoryMatch = activeCategory === 'all' || card.dataset.category === activeCategory;
      const searchMatch = !query || (card.dataset.search || '').includes(query);
      const show = categoryMatch && searchMatch;
      card.classList.toggle('hidden', !show);
      if (show) visible++;
    });
    noResults.classList.toggle('hidden', visible > 0);
  }

  filters.forEach(function (button) {
    button.addEventListener('click', function () {
      activeCategory = button.dataset.category;
      filters.forEach(item => item.classList.toggle('active', item === button));
      applyFilters();
    });
  });

  document.querySelectorAll('[data-side-category]').forEach(function (link) {
    link.addEventListener('click', function (event) {
      event.preventDefault();
      activeCategory = link.dataset.sideCategory;
      filters.forEach(item => item.classList.toggle('active', item.dataset.category === activeCategory));
      applyFilters();
    });
  });

  document.getElementById('news-search').addEventListener('submit', function (event) {
    event.preventDefault();
    applyFilters();
  });
  input.addEventListener('input', applyFilters);
})();
</script>
